fn main() {
    // Inference: no allocation, no training code involved.
    for x in [0.0f64, 0.25, 0.5, 0.75, 1.0] {
        let truth = (-x).exp() * (4.0 * x).cos();
        println!(
            "EXP_COS({x:.2}) = {:+.7}   (true {:+.7})",
            EXP_COS.eval([x]),
            truth
        );
    }
    for p in [[0.2f64, 0.4], [0.6, 0.1], [0.9, 0.9]] {
        let truth = (2.0 * p[0]).sin() * (1.5 * p[1]).cos() + 0.3 * p[0] * p[1];
        println!(
            "SURFACE({p:?}) = {:+.5}   (true {:+.5})",
            SURFACE.eval(p),
            truth
        );
    }
    for x in [0.0f64, 0.3, 0.4, 0.5, 1.0] {
        let truth = (1.0 + (40.0 * (x - 0.4)).exp()).ln() / 40.0;
        println!(
            "BEND({x:.2}) = {:+.6}   (true {:+.6})",
            BEND.eval([x]),
            truth
        );
    }
}
